package com.personal.assistant.module.stock.mapper;public final class StockSectorFundFlowSql{private StockSectorFundFlowSql(){}public static String sectors(){return"select coalesce(w.industry,'未分组') industry,count(*) stock_count,coalesce(sum(s.main_net_inflow),0) main_net_inflow,coalesce(avg(s.main_net_ratio),0) average_main_net_ratio,coalesce(avg(s.change_percent),0) average_change_percent from stock_watch_item w join stock_fund_flow_snapshot s on s.watch_item_id=w.id where w.user_id=#{uid} and w.enabled=true and w.market='CN' and s.quote_time=(select max(x.quote_time) from stock_fund_flow_snapshot x where x.watch_item_id=w.id) group by coalesce(w.industry,'未分组') order by main_net_inflow desc";}}
